def preserve_latest_pending_worksite(apps, schema_editor):
    WorksiteLocation = apps.get_model("portal", "WorksiteLocation")
    database = schema_editor.connection.alias
    intern_ids = list(
        WorksiteLocation.objects.using(database)
        .filter(intern__isnull=False, approval_status="pending")
        .values_list("intern_id", flat=True)
        .distinct()
    )
    for intern_id in intern_ids:
        pending_sites = list(
            WorksiteLocation.objects.using(database)
            .filter(intern_id=intern_id, approval_status="pending")
            .order_by("-created_at", "-pk")
        )
        for duplicate in pending_sites[1:]:
            WorksiteLocation.objects.using(database).filter(pk=duplicate.pk).update(
                approval_status="rejected",
                is_active=False,
                rejection_reason=(
                    "This pending submission was superseded by a newer request "
                    "during the workflow update."
                ),
            )


def preserve_existing_face_enrollments(apps, schema_editor):
    FaceEnrollment = apps.get_model("portal", "FaceEnrollment")
    FaceEnrollmentSubmission = apps.get_model("portal", "FaceEnrollmentSubmission")
    database = schema_editor.connection.alias
    FaceEnrollmentSubmission.objects.using(database).bulk_create(
        [
            FaceEnrollmentSubmission(
                intern_id=enrollment.intern_id,
                encrypted_embedding=enrollment.encrypted_embedding,
                status="approved",
                submitted_at=enrollment.created_at,
            )
            for enrollment in FaceEnrollment.objects.using(database).all().iterator()
        ]
    )


